// src/lib/docs.ts
//
// CRUD over the `docs` table plus version history, diffing, and an
// approval workflow (draft -> review -> approved -> superseded) (mission
// §F). Plain prose docs and "living" docs (whose `isLiving` body blocks are
// periodically regenerated by livingDocs.ts) share this table; only the
// regeneration path differs.
import { db } from "@/db";
import { docs, docVersions } from "@/db/schema";
import { desc, eq } from "drizzle-orm";

export type DocBlock =
  | { type: "prose"; text: string }
  | { type: "live"; refKind: "metric" | "finding" | "okr"; refName: string; entityId?: string; label: string };

export type CreateDocInput = {
  entityId?: string | null;
  title: string;
  docType?: string;
  tags?: string[];
  isLiving?: boolean;
  blocks: DocBlock[];
};

function renderBlocks(blocks: DocBlock[], resolvedValues: Map<string, string>): string {
  return blocks
    .map((b) => {
      if (b.type === "prose") return b.text;
      const key = `${b.refKind}:${b.refName}:${b.entityId ?? ""}`;
      const value = resolvedValues.get(key) ?? "(no current data)";
      return `**${b.label}:** ${value}`;
    })
    .join("\n\n");
}

export { renderBlocks };

export async function createDoc(input: CreateDocInput) {
  // Live docs render with no resolved values yet (freshly created); regenerateLivingDoc() fills them in on first run.
  const placeholderResolved = new Map<string, string>();
  const renderedBody = renderBlocks(input.blocks, placeholderResolved);
  const [row] = await db
    .insert(docs)
    .values({
      entityId: input.entityId ?? null,
      title: input.title,
      body: renderedBody,
      docType: input.docType ?? "note",
      tags: input.tags ?? [],
      isLiving: input.isLiving ?? false,
      status: "draft",
      version: 1,
    })
    .returning();
  await db.insert(docVersions).values({ docId: row.id, version: 1, blocks: input.blocks, renderedBody });
  return row;
}

export async function listDocs(opts: { entityId?: string; isLiving?: boolean; status?: string } = {}) {
  const rows = await db.select().from(docs).orderBy(desc(docs.updatedAt));
  return rows.filter(
    (r) =>
      (opts.entityId === undefined || r.entityId === opts.entityId) &&
      (opts.isLiving === undefined || r.isLiving === opts.isLiving) &&
      (opts.status === undefined || r.status === opts.status)
  );
}

export async function getDoc(id: string) {
  const [row] = await db.select().from(docs).where(eq(docs.id, id)).limit(1);
  return row ?? null;
}

export async function getDocVersions(id: string) {
  return db.select().from(docVersions).where(eq(docVersions.docId, id)).orderBy(desc(docVersions.version));
}

/** Simple line-level diff (no external dependency) — good enough for the reviewer-facing diff view mission §F asks for. */
export function diffLines(before: string, after: string): string {
  const beforeLines = before.split("\n");
  const afterLines = after.split("\n");
  const maxLen = Math.max(beforeLines.length, afterLines.length);
  const out: string[] = [];
  for (let i = 0; i < maxLen; i++) {
    const b = beforeLines[i];
    const a = afterLines[i];
    if (b === a) continue;
    if (b !== undefined) out.push(`- ${b}`);
    if (a !== undefined) out.push(`+ ${a}`);
  }
  return out.join("\n");
}

/** Internal: persist a new rendered version (used by both manual edits and livingDocs.ts regeneration). */
export async function pushDocVersion(docId: string, blocks: DocBlock[], renderedBody: string) {
  const doc = await getDoc(docId);
  if (!doc) throw new Error("Doc not found");
  const newVersion = doc.version + 1;
  const diff = diffLines(doc.body, renderedBody);
  await db.insert(docVersions).values({ docId, version: newVersion, blocks, renderedBody, diffFromPrev: diff });
  const [row] = await db.update(docs).set({ body: renderedBody, version: newVersion, updatedAt: new Date() }).where(eq(docs.id, docId)).returning();
  return { doc: row, diff };
}

export type DocStatus = "draft" | "review" | "approved" | "superseded";
const ALLOWED_TRANSITIONS: Record<DocStatus, DocStatus[]> = {
  draft: ["review"],
  review: ["approved", "draft"],
  approved: ["superseded"],
  superseded: [],
};

export async function transitionDoc(id: string, to: DocStatus, approvedBy?: string) {
  const doc = await getDoc(id);
  if (!doc) throw new Error("Doc not found");
  const from = doc.status as DocStatus;
  if (!ALLOWED_TRANSITIONS[from].includes(to)) {
    throw new Error(`Cannot transition doc from "${from}" to "${to}" — allowed: ${ALLOWED_TRANSITIONS[from].join(", ") || "none"}`);
  }
  if (to === "approved") {
    if (!approvedBy) throw new Error("approvedBy is required to approve a doc");
    const versions = await getDocVersions(id);
    const latest = versions[0];
    if (latest) await db.update(docVersions).set({ approvedBy, approvedAt: new Date() }).where(eq(docVersions.id, latest.id));
  }
  const [row] = await db.update(docs).set({ status: to, updatedAt: new Date() }).where(eq(docs.id, id)).returning();
  return row;
}

/** Export a doc + its version history as a plain-text bundle (mission §F "export"). */
export async function exportDoc(id: string): Promise<string> {
  const doc = await getDoc(id);
  if (!doc) throw new Error("Doc not found");
  const versions = await getDocVersions(id);
  const header = `# ${doc.title}\n\nStatus: ${doc.status} | Version: ${doc.version} | Type: ${doc.docType}\n\n---\n\n`;
  const body = doc.body;
  const history = versions
    .map((v) => `\n\n## Version ${v.version} (${v.createdAt.toISOString().slice(0, 10)})${v.approvedBy ? ` — approved by ${v.approvedBy}` : ""}\n${v.diffFromPrev ?? "(initial version)"}`)
    .join("");
  return header + body + "\n\n---\n# Version history" + history;
}
